	// Hash in the buffer lengths
	MOVQ  ad_len+80(FP), R13
	MOVQ  src_len+56(FP), R14
	ADDQ  R13, R10
	ADCQ  R14, R11
	ADCQ  $0x01, R12
	MOVQ  (BP), AX
